// Collect all items from the three GitHub API nodes.
// Uses $node references so it works regardless of connection chain.
const commitItems = $node['Get Commits'].all();
const issueItems = $node['Get Issues'].all();
const prItems = $node['Get PRs'].all();

// Extract and normalize commit data
const commits = commitItems.map(item => ({
  sha: item.json.sha ? item.json.sha.substring(0, 7) : 'unknown',
  message: item.json.commit ? item.json.commit.message.split('\n')[0] : '',
  author: item.json.commit ? item.json.commit.author.name : 'unknown',
  date: item.json.commit ? item.json.commit.author.date : '',
  url: item.json.html_url || ''
}));

// Extract issues; filter out PRs (GitHub issues endpoint returns both)
const allIssues = issueItems.map(item => ({
  number: item.json.number || 0,
  title: item.json.title || '',
  state: item.json.state || '',
  author: item.json.user ? item.json.user.login : 'unknown',
  closedAt: item.json.closed_at || '',
  url: item.json.html_url || '',
  labels: (item.json.labels || []).map(l => l.name),
  isPR: !!item.json.pull_request
}));
const issues = allIssues.filter(i => !i.isPR);

// Extract PRs and filter to those merged this week
const pulls = prItems.map(item => ({
  number: item.json.number || 0,
  title: item.json.title || '',
  state: item.json.state || '',
  author: item.json.user ? item.json.user.login : 'unknown',
  mergedAt: item.json.merged_at || '',
  url: item.json.html_url || '',
  labels: (item.json.labels || []).map(l => l.name)
}));
const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const mergedPRs = pulls.filter(p => p.mergedAt && p.mergedAt >= weekAgo);

// Build summary statistics
const weekStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const weekEnd = new Date().toISOString().split('T')[0];

const stats = {
  totalCommits: commits.length,
  totalIssuesClosed: issues.length,
  totalPRsMerged: mergedPRs.length,
  weekStart: weekStart,
  weekEnd: weekEnd
};

return [{
  json: {
    stats: stats,
    commits: commits,
    issues: issues,
    pulls: mergedPRs
  }
}];

