// Extract the text content from Claude's response
const claudeResponse = $input.first().json;
const content = claudeResponse.content;

let summaryText = '';
if (Array.isArray(content)) {
  summaryText = content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n\n');
} else if (typeof content === 'string') {
  summaryText = content;
}

// Pull stats from the Combine Data node for the final payload
const combined = $node['Combine Data'].first().json;

return [{
  json: {
    summary: summaryText,
    repository: ($workflow.variables.repoUrl || '').split('/repos/')[1] || $workflow.variables.repoUrl,
    weekStart: combined.stats.weekStart,
    weekEnd: combined.stats.weekEnd,
    stats: combined.stats
  }
}];
